// shade with: the albedo the rim is tinted toward, the geometry's normal the clearcoat takes in
// place of the normal map's, and the tangent and binormal the highlight stretches along.
struct Layers {
    float rim;
    float rim_tint;
    float clearcoat;
    float clearcoat_roughness;
    float anisotropy;
    float3 albedo;
    float3 geometry;
    float3 tangent;
    float3 binormal;
    // Forward+'s transmittance: on, through skin's profile, its color (alpha times the subsurface
    // strength and the light's attenuation), depth and boost.
    bool transmittance;
    bool skin;
    float4 transmittance_color;
    float transmittance_depth;
    float transmittance_boost;
};

